function Badge({children,tone='blue'}:{children:ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
function Btn({children,onClick,primary=false,disabled=false,type='button'}:{children:ReactNode;onClick?:()=>void;primary?:boolean;disabled?:boolean;type?:'button'|'submit'}){return <button type={type} className={'btn '+(primary?'primary':'')} onClick={onClick} disabled={disabled}>{children}</button>}
function Pick({label,value,onChange,options}:{label:string;value:string;onChange:(v:string)=>void;options:string[]}){return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} className="pick"><SelectValue placeholder={label}/></SelectTrigger><SelectContent>{options.map(v=><SelectItem key={v} value={v}>{v}</SelectItem>)}</SelectContent></Select>}
